class JsonSchemaMetric(BaseMetric):
    def __init__(self, schema: dict, threshold: float = {{threshold}}):
        self.threshold = threshold
        self.schema = schema
        self.evaluation_model = "json-schema-validator"

    def measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        import json as json_lib
        actual = (test_case.actual_output or "").strip()
        try:
            data = json_lib.loads(actual)
        except json_lib.JSONDecodeError as e:
            self.score = 0.0
            self.reason = f"JSON 解析失败: {e}"
            self.success = False
            return self.score
        missing = []
        wrong_type = []
        for key, expected_type in self.schema.items():
            if key not in data:
                missing.append(key)
            elif isinstance(expected_type, type):
                if not isinstance(data[key], expected_type):
                    wrong_type.append(f"{key}(expect {expected_type.__name__}, got {type(data[key]).__name__})")
        if missing:
            self.score = 0.0
            self.reason = f"缺少字段: {missing}"
        elif wrong_type:
            self.score = 0.0
            self.reason = f"字段类型错误: {wrong_type}"
        else:
            self.score = 1.0
            self.reason = "JSON 格式和字段类型完全符合预期"
        self.success = self.score >= self.threshold
        return self.score

    async def a_measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        return self.measure(test_case)

    def is_successful(self) -> bool:
        return bool(self.score and self.score >= self.threshold)

    @property
    def __name__(self):
        return "JsonSchema Check"
